begin;
do $$
declare actor uuid:=gen_random_uuid(); other_actor uuid:=gen_random_uuid(); org uuid; other_org uuid; agent uuid; other_agent uuid; run_id uuid; denied boolean; result jsonb; saved jsonb; again jsonb; bad_run uuid;
begin
 insert into auth.users(id,email) values(actor,'discovery-test@example.invalid'),(other_actor,'other-discovery-test@example.invalid');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 org:=public.create_vendor_workspace('Discovery test');
 select id into agent from public.platform_agents where organization_id=org and platform='web';
 denied:=false;
 begin perform public.finish_steward_discovery(gen_random_uuid(),'{}'); exception when insufficient_privilege then denied:=true; end;
 if not denied then raise exception 'Client can forge discoveries'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other_actor,'role','authenticated')::text,true);
 other_org:=public.create_vendor_workspace('Other discovery test');
 select id into other_agent from public.platform_agents where organization_id=other_org and platform='web';
 execute 'reset role';
 execute 'set local role service_role';
 run_id:=((public.reserve_steward_research(actor,org,gen_random_uuid(),jsonb_build_object('question','Find real local business partners','purpose','vendors','location','Tucson','agentId',agent,'collectVendors',true)))->'run'->>'id')::uuid;
 result:='{"answer":"Sourced local discovery for review.","sources":[{"id":1,"url":"https://example.invalid/business"}],"localDiscovery":{"vendors":[{"details":{"name":"Fixture caterer","category":"food","service_areas":["Tucson"],"email":"","phone":"","contact_name":"","notes":"Unverified research candidate"},"source_url":"https://example.invalid/business","source_excerpt":"Test evidence only, not a real business.","links":[{"platform":"website","url":"https://example.invalid/business"}]}],"plan":{"title":"Proposed neighborhood gathering","contribution":"Prepare useful local resources for residents.","connection":"Draft an invitation for review.","gathering":"Compare accessible options before booking.","follow_up":"Verify the candidates and ask for interest."}}}'::jsonb;
 saved:=public.finish_steward_discovery(run_id,result);
 again:=public.finish_steward_discovery(run_id,result);
 if saved<>again or (saved->'savedDiscovery'->>'vendorCount')::int<>1 then raise exception 'Idempotent result failed'; end if;
 if (select count(*) from public.vendors where organization_id=org)<>1 or (select count(*) from public.steward_plans where organization_id=org)<>1 then raise exception 'Duplicate or missing materialization'; end if;
 if (select status from public.vendors where organization_id=org)<>'needs_review' then raise exception 'Unverified vendor promoted'; end if;
 if (select status from public.steward_plans where organization_id=org)<>'draft' then raise exception 'Plan silently approved'; end if;
 bad_run:=((public.reserve_steward_research(actor,org,gen_random_uuid(),jsonb_build_object('question','Find local business partners again','purpose','vendors','agentId',other_agent,'collectVendors',true)))->'run'->>'id')::uuid;
 denied:=false;
 begin perform public.finish_steward_discovery(bad_run,result); exception when others then denied:=true; end;
 if not denied then raise exception 'Cross-organization agent accepted'; end if;
 perform public.finish_steward_research(bad_run,null,'Test denied as expected');
 bad_run:=((public.reserve_steward_research(actor,org,gen_random_uuid(),jsonb_build_object('question','Find business partners without sources','purpose','vendors','agentId',agent,'collectVendors',true)))->'run'->>'id')::uuid;
 saved:=public.finish_steward_discovery(bad_run,jsonb_set(result,'{sources}','[]') || '{"localDiscovery":{"vendors":[{"details":{"name":"Uncited vendor","category":"","service_areas":[],"email":"","phone":"","contact_name":"","notes":""},"source_url":"https://example.invalid/uncited","source_excerpt":"Unsupported evidence must not save","links":[]}],"plan":null}}'::jsonb);
 if (saved->'savedDiscovery'->>'skippedCount')::int<>1 or (select count(*) from public.vendors where organization_id=org)<>1 then raise exception 'Uncited vendor accepted'; end if;
 execute 'reset role';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other_actor,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 if (select count(*) from public.vendors)<>0 or (select count(*) from public.steward_plans)<>0 then raise exception 'Cross-organization read leak'; end if;
 execute 'reset role';
end; $$;
rollback;
